import multiprocessing as mp

class SharedMemory:
    def __init__(self, size):
        self.size = size
        self.memory = mp.RawArray('i', size)

    def read(self, index):
        return self.memory[index]

    def write(self, index, value):
        self.memory[index] = value

    def __del__(self):
        del self.memory

memory = SharedMemory(10)

def worker_process(index):
    memory.write(index, index * 2)
    print(f"Process {mp.current_process().name} wrote {index*2} to index {index}")
    value = memory.read(index)
    print(f"Process {mp.current_process().name} read {value} from index {index}")

processes = []
for i in range(5):
    process = mp.Process(target=worker_process, args=(i,))
    processes.append(process)
    process.start()

for process in processes:
    process.join()

