import threading
import time

def generate_primes(n):
    primes = []
    sieve = [True] * (n+1)
    for p in range(2, int(n**0.5)+1):
        if sieve[p]:
            for i in range(p*p, n+1, p):
                sieve[i] = False
    for p in range(2, n+1):
        if sieve[p]:
            primes.append(p)
    return primes

def generate_primes_multithreaded(n, num_threads):
    primes = []
    sieve = [True] * (n+1)
    threads = []
    chunk_size = (n-1) // num_threads + 1
    for i in range(num_threads):
        start = i * chunk_size + 2
        end = min(start + chunk_size, n+1)
        thread = threading.Thread(target=generate_chunk, args=(sieve, start, end))
        threads.append(thread)
        thread.start()
    for thread in threads:
        thread.join()
    for p in range(2, n+1):
        if sieve[p]:
            primes.append(p)
    return primes

def generate_chunk(sieve, start, end):
    for p in range(2, int(end**0.5)+1):
        if sieve[p]:
            for i in range(max(p*p, (start+p-1)//p * p), end, p):
                sieve[i] = False

start_time = time.time()
primes = generate_primes_multithreaded(100000, 4)
end_time = time.time()

print(f"Generated {len(primes)} prime numbers in {end_time - start_time:.4f} seconds.")

