import time

def generate_primes(n):
    primes = []
    for i in range(2, n+1):
        is_prime = True
        for j in range(2, int(i**0.5)+1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)
    return primes

start_time = time.time()
primes = generate_primes(100000)
end_time = time.time()

print(f"Generated {len(primes)} prime numbers in {end_time - start_time:.4f} seconds.")

