def get_account_balance(api_key, account_id, retries=3, backoff_factor=2):
    headers = {
        "Authorization": f"Bearer {api_key}"
    }
    for attempt in range(retries + 1):
        try:
            response = requests.get(f"https://example.com/api/accounts/{account_id}/balance", headers=headers)
            if response.status_code == 200:
                return response.json()
            elif response.status_code >= 500:
                raise Exception("Server error occurred while fetching account balance")
            else:
                print(f"Unexpected response from server: {response.status_code}")
        except Exception as e:
            print(f"Error fetching account balance: {e}")

        if attempt < retries:
            sleep_time = backoff_factor * (2 ** attempt)
            print(f"Retrying in {sleep_time} seconds...")
            time.sleep(sleep_time)

    raise Exception("Failed to fetch account balance after multiple attempts")

