import pandas as pd

class DataLoader:
    def __init__(self, sales_file, customer_file, product_file):
        self.sales_file = sales_file
        self.customer_file = customer_file
        self.product_file = product_file

    def load_sales_data(self):
        return pd.read_csv(self.sales_file)

    def load_customer_data(self):
        return pd.read_csv(self.customer_file)

    def load_product_data(self):
        return pd.read_csv(self.product_file)

def load_data(loader):
    # Load data from multiple sources
    sales_data = loader.load_sales_data()
    customer_data = loader.load_customer_data()
    product_data = loader.load_product_data()

    # Merge data into a single dataframe
    merged_data = pd.merge(sales_data, customer_data, on="customer_id")
    merged_data = pd.merge(merged_data, product_data, on="product_id")

    return merged_data

