import os

def transfer_video_files(source_dir, dest_dir):
    try:
        shutil.copytree(source_dir, dest_dir)
    except (shutil.Error, OSError) as e:
        print(f"Error occurred while copying directory tree from '{source_dir}' to '{dest_dir}': {e}")
        if isinstance(e, shutil.DestinationExistsError):
            print("Destination already exists.")
        elif isinstance(e, shutil.SameFileError):
            print("Source and destination are the same file.")
        elif isinstance(e, PermissionError):
            print("Permission error occurred.")
        elif isinstance(e, FileNotFoundError):
            print("Source or destination path not found.")
        elif isinstance(e, NotADirectoryError):
            print("Source or destination is not a directory.")
        elif isinstance(e, OSError):
            print("OS error occurred.")
            if e.errno == os.errno.ENOSPC:
                print("Insufficient disk space.")
            elif e.errno == os.errno.EIO:
                print("I/O error occurred.")
            elif e.errno == os.errno.EROFS:
                print("Read-only file system.")
            else:
                print(f"Unknown OS error ({e.errno}).")
    except Exception as e:
        print(f"Unexpected error occurred: {e}")

