        self.data = data

    def search(self, query):
        left = 0
        right = len(self.data) - 1
        results = []
        while left <= right:
            mid = (left + right) // 2
            if query == self.data[mid]:
                results.append(self.data[mid])
                break
            elif query < self.data[mid]:
                right = mid - 1
            else:
                left = mid + 1
        return results

