import requests

def get_vars(url, row_num, col_num, skip_missing=False):
    response = requests.get(url)
    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table')

    rows = table.find_all('tr')
    if len(rows) < row_num:
        if skip_missing:
            return None
        else:
            raise ValueError("Row number out of range.")
    cols = rows[row_num-1].find_all('td')
    if len(cols) < col_num:
        if skip_missing:
            return None
        else:
            raise ValueError("Column number out of range.")
    var = cols[col_num-1].text.strip()
    return var

