def cache(func):
    results = {}
    def wrapper(*args, **kwargs):
        key = str(args) + str(kwargs)
        if key in results and (time.time() - results[key]['timestamp']) < CACHE_DURATION_SECONDS:
            print("Cache hit!")
            return results[key]['result']
        else:
            print("Cache miss!")
            result = func(*args, **kwargs)
            results[key] = {'result': result, 'timestamp': time.time()}
