class DataProcessor:
    def __init__(self, num_threads):
        self.data_queue = PriorityQueue()
        self.threads = []
        for _ in range(num_threads):
            t = threading.Thread(target=self._worker)
            t.daemon = True
            t.start()
            self.threads.append(t)

    def add_data(self, priority, data):
        task = (priority, data)
        self.data_queue.put(task)

    def _worker(self):
        while True:
            if not self.data_queue.empty():
                priority, data = self.data_queue.get()
                process_data(data)
            else:
                time.sleep(0.1)

    def join(self):
        for thread in self.threads:
            thread.join()

