def binary_to_decimal(binary_num):
    decimal_num = 0
    for i in range(len(binary_num)):
        digit = int(binary_num[i])
        power = len(binary_num) - i - 1
        decimal_num += digit * math.pow(2, power)
    return int(decimal_num)

