import requests
import time

CACHE_EXPIRATION_TIME = 1800 # seconds

class WeatherCache:
    def __init__(self):
        self.cache = {}

    def get(self, key):
        value, expiration_time = self.cache.get(key, (None, None))
        if expiration_time is not None and time.time() > expiration_time:
            del self.cache[key]
            value, expiration_time = None, None
        return value

    def set(self, key, value, expiration_time):
        self.cache[key] = (value, time.time() + expiration_time)

weather_cache = WeatherCache()

