import os

class FileHandler:
    def __init__(self, file_path):
        self.file_path = file_path

    def __enter__(self):
        self.file = open(self.file_path, 'w')
        return self.file

    def __exit__(self, exc_type, exc_val, traceback):
        self.file.close()

