import time

def publish_content(content, retries=3, backoff_factor=2):
    for attempt in range(retries + 1):
        try:
            response = requests.post("https://example.com/publish", data=content)
            if response.status_code == 200:
                return response.json()
            elif response.status_code == 401:
                raise Exception("Authentication failed. Please check your credentials.")
            elif response.status_code == 429:
                print(f"Rate limit exceeded. Retrying in {response.headers['Retry-After']} seconds...")
                time.sleep(int(response.headers['Retry-After']))
            else:
                raise Exception("Failed to publish content")
        except Exception as e:
            print(f"Error publishing content: {e}")

        if attempt < retries:
            sleep_time = backoff_factor * (2 ** attempt)
            print(f"Retrying in {sleep_time} seconds...")
            time.sleep(sleep_time)

    raise Exception("Failed to publish content after multiple attempts")

