import csv
import logging

class InvalidDataFormatError(Exception):
    pass

class DoubleBookingError(Exception):
    pass

class IncompletePassengerInfoError(Exception):
    pass

def parse_csv(file_path):
    bookings = []
    try:
        with open(file_path, 'r') as file:
            reader = csv.reader(file)
            for row in reader:
                if len(row) != 4:
                    raise InvalidDataFormatError("Invalid data format")
                booking = {"name": row[0], "flight_number": row[1], "date": row[2], "seat_number": row[3]}
                if booking in bookings:
                    raise DoubleBookingError(f"Double booking detected: {booking}")
                if not all(booking.values()):
                    raise IncompletePassengerInfoError(f"Incomplete passenger information: {booking}")
                bookings.append(booking)
    except FileNotFoundError:
        logging.error(f"File '{file_path}' not found.")
        print(f"Error: The file '{file_path}' could not be found. Please make sure the file exists and is in the correct location.")
        return None
    except InvalidDataFormatError as e:
        logging.error(str(e))
        print(f"Error: {str(e)}")
        return None
    except DoubleBookingError as e:
        logging.error(str(e))
        print(f"Error: {str(e)}")
        return None
    except IncompletePassengerInfoError as e:
        logging.error(str(e))
        print(f"Error: {str(e)}")
        return None

    return bookings

