class PhysicsEngine:
    def __init__(self, num_threads=1):
        self.gravity = 9.8
        self.objects = []
        self.num_threads = num_threads

    def add_object(self, obj):
        self.objects.append(obj)

    def update(self, delta_time):
        if self.num_threads == 1:
            for obj in self.objects:
                obj.update(delta_time)
                obj.apply_force((0, -self.gravity * obj.mass))
        else:
            threads = []
            chunk_size = len(self.objects) // self.num_threads
            for i in range(self.num_threads):
                start_index = i * chunk_size
                end_index = (i + 1) * chunk_size if i < self.num_threads - 1 else len(self.objects)
                thread = threading.Thread(target=self._update_objects, args=(delta_time, start_index, end_index))
                threads.append(thread)
                thread.start()
            for thread in threads:
                thread.join()

    def _update_objects(self, delta_time, start_index, end_index):
        for obj in self.objects[start_index:end_index]:
            obj.update(delta_time)
            obj.apply_force((0, -self.gravity * obj.mass))

