import random
from itertools import combinations

def generate_color():
    r = random.randint(0, 255)
    g = random.randint(0, 255)
    b = random.randint(0, 255)
    return (r, g, b)

def generate_palette(num_colors):
    colors = []
    for i in range(num_colors):
        colors.append(generate_color())
    return colors

def suggest_accessible_combinations(palette):
    accessible_combinations = []
    for c1, c2 in combinations(palette, 2):
        contrast_ratio = calculate_contrast_ratio(c1, c2)
        if contrast_ratio >= 4.5:
            accessible_combinations.append((c1, c2))
    return accessible_combinations

def calculate_contrast_ratio(color1, color2):
    l1 = calculate_luminance(color1)
    l2 = calculate_luminance(color2)
    lighter = max(l1, l2)
    darker = min(l1, l2)
    return (lighter + 0.05) / (darker + 0.05)

def calculate_luminance(color):
    r, g, b = color
    r = r / 255.0
    g = g / 255.0
    b = b / 255.0
    if r <= 0.03928:
        r = r / 12.92
    else:
        r = ((r + 0.055) / 1.055) ** 2.4
    if g <= 0.03928:
        g = g / 12.92
    else:
        g = ((g + 0.055) / 1.055) ** 2.4
    if b <= 0.03928:
        b = b / 12.92
    else:
        b = ((b + 0.055) / 1.055) ** 2.4
    return 0.2126 * r + 0.7152 * g + 0.0722 * b

