        super().__init__(target=target, args=args)
        self.timeout = timeout
        self.daemon = True

    def run(self):
        self.result = None
        try:
            self.result = self._target(*self._args, **self._kwargs)
        except Exception as e:
            self.exception = e

    def join(self, timeout=None):
        super().join(timeout=self.timeout)
        if self.is_alive():
