import sublime_plugin

class HighlightMatchingParentheses(sublime_plugin.EventListener):
    def on_selection_modified(self, view):
        # Get the current selection
        sel = view.sel()[0]

        # Get the character at the beginning of the selection
        char = view.substr(sel.begin() - 1)

        # Check if it's an opening or closing parenthesis
        if char == '(':
            # Find the matching closing parenthesis
            end = view.find('\)', sel.end())
            if end:
                # Highlight the parentheses
                view.add_regions('matching_parentheses', [sel, end], 'comment', '', sublime.DRAW_OUTLINED)
        elif char == ')':
            # Find the matching opening parenthesis
            start = view.find('\(', 0, sel.begin())
            if start:
                # Highlight the parentheses
                view.add_regions('matching_parentheses', [start, sel], 'comment', '', sublime.DRAW_OUTLINED)
        else:
            # Clear any existing highlights
            view.erase_regions('matching_parentheses')

