import zipfile

def compress_files(source_path, dest_path):
    if os.path.isdir(source_path):
        with zipfile.ZipFile(dest_path, mode="w") as archive:
            for root, dirs, files in os.walk(source_path):
                for file in files:
                    archive.write(os.path.join(root, file))
    else:
        with zipfile.ZipFile(dest_path, mode="w") as archive:
            archive.write(source_path)

def decompress_files(source_path, dest_path):
    with zipfile.ZipFile(source_path, mode="r") as archive:
        archive.extractall(dest_path)

