def sort_list(products):
    """
    Sorts a list of products by price in ascending order.

    This function takes in a list of dictionaries representing products and sorts them based on their price in ascending order. Each dictionary should have a 'price' key with a numeric value. If the input is not a list or if any of the dictionaries do not have a 'price' key, an exception will be raised.

    Parameters:
        products (list): A list of dictionaries representing products. Each dictionary should have a 'price' key with a numeric value.

    Returns:
        list: The sorted list of products.
    """
    if not isinstance(products, list):
        raise TypeError("Input must be a list.")
    for product in products:
        if not isinstance(product, dict) or 'price' not in product:
            raise ValueError("Each item in the list must be a dictionary with a 'price' key.")
    return sorted(products, key=lambda p: p['price'])

