class HuffmanCoding:
    def __init__(self, data):
        self.data = data
        self.freq = {}
        for symbol in data:
            if symbol in self.freq:
                self.freq[symbol] += 1
            else:
                self.freq[symbol] = 1
        self.codes = {}

    def build_tree(self):
        nodes = []
        for symbol, freq in self.freq.items():
            nodes.append((freq, symbol))
        while len(nodes) > 1:
            nodes.sort()
            left = nodes.pop(0)
            right = nodes.pop(0)
            node = (left[0] + right[0], left, right)
            nodes.append(node)
        return nodes[0]

    def generate_codes(self, node, code=''):
        if isinstance(node[1], str):
            self.codes[node[1]] = code
        else:
            self.generate_codes(node[1], code + '0')
            self.generate_codes(node[2], code + '1')

    def compress(self):
        self.build_tree()
        self.generate_codes(self.build_tree())
        compressed_data = ''
        for symbol in self.data:
            compressed_data += self.codes[symbol]
        return compressed_data

