import re

def is_valid_email(email):
    if len(email) < 5:
        return False
    elif not re.match(r"[^@]+@[^@]+\.[^@]+", email):
        return False
    else:
        parts = email.split("@")
        username = parts[0]
        domain = parts[1]
        if len(username) < 1 or len(domain) < 3:
            return False
        elif "." not in domain:
            return False
        elif domain.startswith(".") or domain.endswith("."):
            return False
        else:
            return True

