import os

def find_executable_path(executable_name):
    if os.name == "nt":
        paths = os.environ["PATH"].split(";")
    else:
        paths = os.environ["PATH"].split(":")

    for path in paths:
        full_path = os.path.join(path, executable_name)
        if os.path.exists(full_path) and os.access(full_path, os.X_OK):
            return full_path

    raise ValueError(f"Could not find {executable_name} in PATH")

