def get_most_frequent_words(text, category):
    words = text.split()
    word_count = {}
    for word in words:
        if word not in word_count:
            word_count[word] = 0
        word_count[word] += 1

    sorted_words = sorted(word_count.items(), key=lambda x: x[1], reverse=True)
    most_frequent_words = []
    for word, count in sorted_words:
        if len(most_frequent_words) == 10:
            break
        if word in category:
            most_frequent_words.append(word)
        elif len(most_frequent_words) + (len(sorted_words) - sorted_words.index((word, count))) < 10:
