        filter_func = self._build_filter()
        return list(filter(filter_func, string))

    def _build_filter(self):
        def non_recursive_match(pattern, string):
            while pattern:
                if pattern == "$" and not string:
                    return True
                elif len(pattern) > 1 and pattern[1] in "*?":
                    if pattern[1] == "*":
                        pattern = pattern[2:]
                        while string and (pattern[0] == string[0] or pattern[0] == "."):
                            string = string[1:]
                    else:
                        if string and (pattern[0] == string[0] or pattern[0] == "."):
