class RegexEngine:
    def __init__(self, pattern):
        self.pattern = pattern

    def match(self, string):
        filter_func = self._build_filter()
        return list(filter(filter_func, string))

    def _build_filter(self):
        def recursive_match(pattern, string):
            if not pattern:
                return True
            elif pattern == "$" and not string:
                return True
            elif len(pattern) > 1 and pattern[1] in "*?":
                if pattern[1] == "*":
                    return recursive_match(pattern[2:], string) or (string and recursive_match(pattern, string[1:]))
                else:
                    return (string and recursive_match(pattern[2:], string[1:])) or recursive_match(pattern[2:], string)
            elif string and pattern[0] in {string[0], "."}:
                return recursive_match(pattern[1:], string[1:])
            else:
                return False

        return lambda x: recursive_match(self.pattern, x)

regex = RegexEngine("a*b")
print(regex.match(["a", "ab", "abc", "bc"]))

