def get_nearby_places(latitude, longitude):
    try:
        url = f"https://api.example.com/places?lat={latitude}&long={longitude}"
        response = requests.get(url)
        if response.status_code != 200:
            raise APIError(f"Failed to retrieve nearby places for location ({latitude}, {longitude}).", response.status_code)
        places = response.json()
        return places
