class PaymentRequestError(Exception):
    pass

def make_payment_request(url, data, retries=3, delay=5):
    for attempt in range(retries):
        try:
            response = requests.post(url, json=data)
            if response.status_code == 200:
                return True
            else:
                raise PaymentRequestError(f"Payment request failed. Status code: {response.status_code}")
        except (requests.exceptions.RequestException, requests.exceptions.Timeout) as e:
            print(f"Network error or timeout occurred: {e}")

        if attempt < retries - 1:
            backoff_time = delay * 2 ** attempt
            print(f"Retrying after {backoff_time} seconds... (Attempt {attempt + 2}/{retries})")
            time.sleep(backoff_time)

