import math

def distance(point1, point2):
    return math.sqrt((point1[0] - point2[0])**2 + (point1[1] - point2[1])**2)

def closest_pair_of_points(points):
    def merge(left, right):
        result = []
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i][1] < right[j][1]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1
        result.extend(left[i:])
        result.extend(right[j:])
        return result

    def divide_and_conquer(points):
        if len(points) <= 3:
            return brute_force(points)
        mid = len(points) // 2
        left = points[:mid]
        right = points[mid:]
        dl = divide_and_conquer(left)
        dr = divide_and_conquer(right)
        d = min(dl, dr)
        strip = [p for p in points if abs(p[0] - points[mid][0]) < d]
        return merge_strip(strip, d)

    def brute_force(points):
        min_distance = float('inf')
        for i in range(len(points)):
            for j in range(i+1, len(points)):
                dist = distance(points[i], points[j])
                if dist < min_distance:
                    min_distance = dist
        return min_distance

    def merge_strip(strip, d):
        strip.sort(key=lambda x: x[1])
        min_distance = d
        for i in range(len(strip)):
            j = i + 1
            while j < len(strip) and (strip[j][1] - strip[i][1]) < min_distance:
                dist = distance(strip[i], strip[j])
                if dist < min_distance:
                    min_distance = dist
                j += 1
        return min_distance

    points.sort()
    return divide_and_conquer(points)

