import threading
from queue import Queue

class ThreadSafeDataProcessor:
    def __init__(self, num_threads=4):
        self.data_queue = Queue()
        self.result_queue = Queue()
        self.threads = []
        for i in range(num_threads):
            t = threading.Thread(target=self._processing_worker)
            t.daemon = True
            t.start()
            self.threads.append(t)

    def _processing_worker(self):
        while True:
            data_chunk = self.data_queue.get()
            if data_chunk is None:
                break
            result = self._process_data(data_chunk)
            self.result_queue.put(result)

    def _process_data(self, data):
        # Simulate data cleaning and preprocessing
        cleaned_data = data.dropna()
        return cleaned_data

    def process_data(self, data):
        self.data_queue.put(data)

    def get_results(self):
        results = []
        while not self.result_queue.empty():
            result = self.result_queue.get()
            results.append(result)
        return pd.concat(results)

def preprocess_data(data):
    processor = ThreadSafeDataProcessor()
    chunk_size = len(data) // processor.num_threads
    chunks = [data[i:i+chunk_size] for i in range(0, len(data), chunk_size)]
    for chunk in chunks:
        processor.process_data(chunk)
    results = processor.get_results()
    return results

