def generate_report(transactions):
    customers = {}
    for transaction in transactions:
        customer_id = transaction['customer_id']
        if customer_id not in customers:
            customers[customer_id] = {'total_spent': 0, 'num_transactions': 0}
        customers[customer_id]['total_spent'] += transaction['amount']
        customers[customer_id]['num_transactions'] += 1

    avg_revenue_per_customer = sum(customer['total_spent'] / customer['num_transactions'] for customer in customers.values()) / len(customers)
