class Node:
    def __init__(self, data):
        self.left = None
        self.right = None
        self.data = data

def insert_node(root, node):
    if root is None:
        root = node
    else:
        if root.data < node.data:
            if root.right is None:
                root.right = node
            else:
                insert_node(root.right, node)
        else:
            if root.left is None:
                root.left = node
            else:
                insert_node(root.left, node)

def search_profiles(profiles, attribute, value):
    sorted_profiles = sorted(profiles, key=lambda x: x[attribute])
    root = Node(sorted_profiles[len(sorted_profiles) // 2])
    for profile in sorted_profiles:
        insert_node(root, Node(profile))
    current = root
    while current is not None:
        if current.data[attribute] == value:
            return current.data
        elif current.data[attribute] < value:
            current = current.right
        else:
            current = current.left
    return None

