def generate_report(student_name, grades):
    # Generate a report for the student with their name and grades
    report = f"Report for {student_name}\n\n"
    total_score = 0
    for subject, score in grades.items():
        report += f"{subject}: {score}\n"
        total_score += score
    report += f"\nTotal Score: {total_score}"
    return report

def save_file(filename, data):
    try:
        if filename.endswith(".pdf"):
            c = canvas.Canvas(filename)
            c.drawString(100, 750, data)
            c.save()
        elif filename.endswith(".csv"):
            with open(filename, "w") as f:
                writer = csv.writer(f)
                for row in data:
                    writer.writerow(row)
        else:
            raise ValueError("Invalid file format. Only PDF and CSV are supported.")
    except Exception as e:
        print(f"Error while saving file: {e}")

