            if len(self.cache) > 100:
                self.evictions += 1
                # code to evict least recently used item from cache dictionary
            return data

    def get_hit_rate(self):
        total_requests = self.hits + self.misses
        if total_requests == 0:
            return 0
        else:
            return self.hits / total_requests

