def calculate_sharpe_ratio(returns, risk_free_rate):
    mean_return = sum(returns) / len(returns)
    std_dev = (sum((x - mean_return) ** 2 for x in returns) / len(returns)) ** 0.5
    excess_returns = list(map(lambda r: r - risk_free_rate, returns))
    mean_excess_return = sum(excess_returns) / len(excess_returns)
    sharpe_ratio = mean_excess_return / std_dev
    return sharpe_ratio

