import re

class SentimentAnalyzer:
    def __init__(self, positive_words, negative_words):
        self.positive_words = positive_words
        self.negative_words = negative_words

    def process_data(self, tweets):
        cleaned_tweets = []
        for tweet in tweets:
            if 'RT' not in tweet and 'spam' not in tweet:
                cleaned_tweet = re.sub(r'http\S+', '', tweet)
                cleaned_tweets.append(cleaned_tweet)
        return cleaned_tweets

    def classify_sentiment(self, tweet):
        words = tweet.split()
        num_positive = sum(1 for word in words if word in self.positive_words)
        num_negative = sum(1 for word in words if word in self.negative_words)
        if num_positive > num_negative:
            return 'positive'
        elif num_negative > num_positive:
            return 'negative'
        else:
            return 'neutral'

