import os

def backup_data(source_dir, dest_dir):
    try:
        # Check available disk space before backup
        total, used, free = shutil.disk_usage(dest_dir)
        if free < shutil.disk_usage(source_dir).total:
            # Clean up unnecessary files to free up space
            for root, dirs, files in os.walk(dest_dir):
                for file in files:
                    path = os.path.join(root, file)
                    try:
                        os.remove(path)
                        print(f"Removed file: {path}")
                    except Exception as e:
                        print(f"Error removing file: {e}")

        # Create backup
        shutil.copytree(source_dir, dest_dir)
        print("Backup completed successfully.")
