def read_file(file_path):
    with open(file_path, 'r') as file:
        data = file.read()
    return data

def parse_data(data):
    lines = data.split('\n')
    headers = lines[0].split(',')
    rows = []
    for line in lines[1:]:
        if line:
            row = line.split(',')
            rows.append(row)
    return headers, rows

def perform_analysis(headers, rows):
    results = {}
    for i, header in enumerate(headers):
        column_values = [float(row[i]) for row in rows]
        results[header] = {
            'mean': sum(column_values) / len(column_values),
            'max': max(column_values),
            'min': min(column_values)
        }
    return results

def format_output(results):
    output = ""
    for header, stats in results.items():
        output += f"{header}: \n"
        output += f"\tMean: {stats['mean']:.2f}\n"
        output += f"\tMax: {stats['max']:.2f}\n"
        output += f"\tMin: {stats['min']:.2f}\n"
    return output

def save_results(output_file_path, output):
    with open(output_file_path, 'w') as file:
        file.write(output)

def analyze_data(file_path):
    data = read_file(file_path)
    headers, rows = parse_data(data)
    results = perform_analysis(headers, rows)
    output = format_output(results)
    output_file_path = os.path.splitext(file_path)[0] + "_results.txt"
    save_results(output_file_path, output)

file_path = "data.csv"
analyze_data(file_path)

