import subprocess

def check_latency(ip_address):
    ping = subprocess.Popen(["ping", "-c", "3", ip_address], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    out, error = ping.communicate()
    if error:
        print(f"Error pinging {ip_address}: {error}")
    else:
        lines = out.decode('utf-8').split('\n')
        time_line = lines[-2]
        time = int(time_line.split('=')[-1].split()[0])
        if time > 100:
            print(f"High latency detected for {ip_address}. Latency: {time} ms")
        else:
            print(f"Latency for {ip_address} is normal. Latency: {time} ms")

