import time

class CDNCache:
    def __init__(self, num_partitions):
        self.num_partitions = num_partitions
        self.partitions = [[] for _ in range(num_partitions)]
        self.access_counts = {}

    def get_partition_index(self, filename):
        # Partition based on access count
        if filename not in self.access_counts:
            self.access_counts[filename] = 0
        partition_index = self.access_counts[filename] % self.num_partitions
        self.access_counts[filename] += 1
        return partition_index

    def get_file(self, filename):
        partition_index = self.get_partition_index(filename)
        for cached_filename, file_data in self.partitions[partition_index]:
            if cached_filename == filename:
                return file_data
        # Simulate network latency
        time.sleep(0.1)
        file_data = self._fetch_file_from_server(filename)
        self.partitions[partition_index].append((filename, file_data))
        return file_data

    def _fetch_file_from_server(self, filename):
        # Simulate server request
        return f"File data for {filename}"

