import json

class TranslationManager:
    def __init__(self):
        self.translations = {}

    def load_translations(self, language):
        if language not in self.translations:
            with open(f"{language}.json", "r") as f:
                translations = json.load(f)
                self.translations[language] = translations
        return self.translations[language]

    def translate(self, text, language, count=1):
        translations = self.load_translations(language)
        if text in translations:
            if isinstance(translations[text], dict):
                if count == 0:
                    return translations[text]["zero"]
                elif count == 1:
                    return translations[text]["one"]
                elif count == 2:
                    return translations[text]["two"]
                else:
                    return translations[text]["other"]
            else:
                return translations[text]
        else:
            return text

