import time

def expensive_computation(n):
    time.sleep(1)
    return n ** 2

class LazyList:
    def __init__(self, length, compute_func):
        self.length = length
        self.compute_func = compute_func
        self.cache = {}

    def __getitem__(self, index):
        if index < 0 or index >= self.length:
            raise IndexError("Index out of range")
        if index not in self.cache:
            self.cache[index] = self.compute_func(index)
        return self.cache[index]

    def __len__(self):
        return self.length

    def map(self, func):
        return LazyList(self.length, lambda i: func(self[i]))

    def filter(self, predicate):
        return LazyList(self.length, lambda i: self[i] if predicate(self[i]) else None)

    def reduce(self, func, initial=None):
        result = initial
        for i in range(self.length):
            if i in self.cache:
                value = self.cache[i]
            else:
                value = self.compute_func(i)
                self.cache[i] = value
            if result is None:
                result = value
            else:
                result = func(result, value)
        return result

