import itertools

def traveling_salesman_problem(points):
    n = len(points)
    memo = {(frozenset([i]), i): (float('inf'), None) for i in range(n)}
    memo[(frozenset(), 0)] = (0, None)

    for size in range(1, n):
        for subset in itertools.combinations(range(n), size):
            subset = frozenset(subset)
            for dest in subset:
                prev = subset - {dest}
                memo[(subset, dest)] = min(
                    (memo[(prev, k)][0] + ((points[k][0] - points[dest][0])**2 + (points[k][1] - points[dest][1])**2)**0.5, k)
                    for k in prev if dest != k)

    path = []
    subset = frozenset(range(1, n))
    dest = 0
    _, prev = memo[(subset, dest)]
    while prev is not None:
        path.append(prev)
        subset = subset - {prev}
        _, prev = memo[(subset, prev)]
    return [points[i] for i in reversed(path)], memo[(frozenset(range(1, n)), 0)][0]

points = [(0, 0), (1, 1), (2, 2), (3, 3)]
best_path, min_distance = traveling_salesman_problem(points)
print(f"Best path: {best_path}, Min distance: {min_distance:.2f}")

