    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    queue = [(start, 0)]
    visited = set()
    while queue:
        (current_node, current_distance) = queue.pop(0)
        if current_node == end:
            return current_distance
        if current_node in visited:
