import requests
from functools import lru_cache, wraps

def cache(bypass=False):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if bypass:
                return func(*args, **kwargs)
            else:
                return wrapper.cache_get_or_set(*args, **kwargs)

        def cache_get_or_set(*args, **kwargs):
            key = str(args) + str(kwargs)
            if key not in cache.cache:
                value = func(*args, **kwargs)
                cache.cache[key] = value
            return cache.cache[key]

        wrapper.cache = {}
        wrapper.cache_get_or_set = cache_get_or_set
        return wrapper

    return decorator

