    def visit(self, node):
        if isinstance(node, ast.AST):
            if hasattr(node, 'lineno') and hasattr(node, 'col_offset'):
                line = node.lineno
                col = node.col_offset
                if '\t' in node.__repr__():
                    self.errors.append(f"Line {line}, column {col}: Indentation should use spaces instead of tabs.")

def check_indentation(filename):
    with open(filename) as file:
        source = file.read()
    tree = ast.parse(source)
    checker = SpaceIndentationChecker()
    checker.visit(tree)
    return checker.errors

if __name__ == "__main__":
    filename = sys.argv[1]
    errors = check_indentation(filename)
    if errors:
        print("Indentation errors found:")
        for error in errors:
            print(error)
    else:
        print("No indentation errors found.")

