import errno
from contextlib import contextmanager

@contextmanager
def file_lock(filename):
    lock_file = open(filename, 'w')
    while True:
        try:
            fcntl.flock(lock_file, fcntl.LOCK_EX | fcntl.LOCK_NB)
            break
        except IOError as e:
            if e.errno != errno.EAGAIN:
                raise
            else:
                time.sleep(0.1)
    try:
        yield lock_file
    finally:
        fcntl.flock(lock_file, fcntl.LOCK_UN)
        lock_file.close()

def backup_database():
