def retry_on_error(func):
    def wrapper(*args, **kwargs):
        retries = 3
        while retries > 0:
            try:
                result = func(*args, **kwargs)
                return result
            except (requests.exceptions.RequestException, ValueError) as e:
                print(f"Error occurred: {e}")
                retries -= 1
                if retries == 0:
                    raise
                time.sleep(5)
    return wrapper

