from datetime import date

class Task:
    def __init__(self, description, team_member, priority, due_date, completed):
        self.description = description
        self.team_member = team_member
        self.priority = priority
        self.due_date = due_date
        self.completed = completed

tasks = [
    Task("Write report", "John", 1, date(2022, 1, 15), False),
    Task("Prepare presentation", "Jane", 2, date(2022, 1, 20), True),
    Task("Update website", "John", 3, date(2022, 1, 25), False),
]

def filter_tasks(tasks, team_member=None, priority=None, due_date=None, status=None):
    filtered_tasks = tasks

    if team_member:
        filtered_tasks = filter(lambda task: task.team_member == team_member, filtered_tasks)

    if priority:
        filtered_tasks = filter(lambda task: task.priority == priority, filtered_tasks)

    if due_date:
        filtered_tasks = filter(lambda task: task.due_date == due_date, filtered_tasks)

    if status:
        if status == 'completed':
            filtered_tasks = filter(lambda task: task.completed, filtered_tasks)
        elif status == 'pending':
            filtered_tasks = filter(lambda task: not task.completed, filtered_tasks)

    return list(filtered_tasks)

filtered_tasks = filter_tasks(tasks, team_member="John", priority=3, status='pending')
for task in filtered_tasks:
    print(task.description)

