import datetime

def schedule_event(event_name, start_date, end_date, recurrence):
    event_dates = []
    current_date = start_date
    while current_date <= end_date:
        event_dates.append(current_date)
        if recurrence == 'daily':
            current_date += datetime.timedelta(days=1)
        elif recurrence == 'weekly':
            current_date += datetime.timedelta(weeks=1)
        elif recurrence == 'monthly':
            current_month = current_date.month
            current_year = current_date.year
            if current_month == 12:
                next_month = 1
                next_year = current_year + 1
            else:
                next_month = current_month + 1
                next_year = current_year
            days_in_next_month = (datetime.date(next_year, next_month, 1) - datetime.date(current_year, current_month, 1)).days
            if current_date.day > days_in_next_month:
                current_date = current_date.replace(day=days_in_next_month)
            current_date = current_date.replace(month=next_month)
        else:
            raise ValueError("Invalid recurrence value")
    return event_dates

