def parallel_word_count(file_path):
    num_threads = 4
    with open(file_path) as f:
        lines = f.readlines()
    chunk_size = len(lines) // num_threads
    threads = []
    for i in range(num_threads):
        start = i * chunk_size
        end = (i + 1) * chunk_size if i < num_threads - 1 else len(lines)
        t = threading.Thread(target=word_count, args=(lines[start:end],))
        threads.append(t)
        t.start()
    total_words = sum([t.join() for t in threads])
    return total_words

