import time
import threading

def schedule_task(task, interval=None, start_time=None):
    if not interval and not start_time:
        raise ValueError("Either interval or start_time must be provided.")
    if interval and start_time:
        raise ValueError("Only one of interval or start_time can be provided.")

    def run_task():
        task()
        if interval:
            threading.Timer(interval, run_task).start()

    if start_time:
        delay = (start_time - time.time()) % interval
        threading.Timer(delay, run_task).start()
    else:
        run_task()

def example_task():
