def shortest_path(graph, start, end):
    stack = [(start, [start])]
    while stack:
        (node, path) = stack.pop()
        if node == end:
            return path
        if node not in graph:
            continue
        for neighbor in graph[node]:
            if neighbor not in path:
                stack.append((neighbor, path + [neighbor]))
    return None

