class SharedResource:
    def __init__(self):
        self.value = 0
        self.lock = threading.Lock()
        self.condition = threading.Condition(lock=self.lock)

    def increment(self):
        with self.lock:
            while self.value >= 5:
                self.condition.wait()
            self.value += 1
            print(f"Incremented to {self.value}")
            self.condition.notify_all()

    def decrement(self):
        with self.lock:
            while self.value <= 0:
                self.condition.wait()
            self.value -= 1
            print(f"Decremented to {self.value}")
            self.condition.notify_all()

