from django.http import HttpResponse, JsonResponse
from django.views.decorators.csrf import csrf_exempt
from django.views import View
from .models import Order
import json
from xml.etree.ElementTree import fromstring

class CreateOrderView(View):
    @csrf_exempt
    def dispatch(self, request, *args, **kwargs):
        content_type = request.content_type.split(';')[0]
        if content_type == 'application/json':
            try:
                request.json_data = json.loads(request.body)
            except ValueError:
                return JsonResponse({'error': 'Invalid JSON'}, status=400)
        elif content_type == 'application/xml':
            try:
                request.xml_data = fromstring(request.body)
            except Exception:
                return JsonResponse({'error': 'Invalid XML'}, status=400)
        return super().dispatch(request, *args, **kwargs)

    def post(self, request):
        if hasattr(request, 'json_data'):
            data = request.json_data
        elif hasattr(request, 'xml_data'):
            data = {
                'customer_name': request.xml_data.find('customer_name').text,
                'product_name': request.xml_data.find('product_name').text,
                'quantity': request.xml_data.find('quantity').text,
                'price': request.xml_data.find('price').text,
            }
        else:
            data = request.POST

        order = Order.objects.create(
            customer_name=data['customer_name'],
            product_name=data['product_name'],
            quantity=data['quantity'],
            price=data['price']
        )
        return HttpResponse(f"Order created with id {order.id}")

