import numpy as np

def apply_filter(image, filter):
    height, width = image.shape[:2]
    for i in range(height):
        for j in range(width):
            pixel = image[i][j]
            filtered_pixel = filter(pixel)
            image[i][j] = filtered_pixel
    return image

def grayscale(pixel):
    r, g, b = pixel
    gray_value = (r + g + b) // 3
    return (gray_value, gray_value, gray_value)

