import time

class Cache:
    def __init__(self):
        self.cache = {}
        self.ttl_cache = {}

    def get(self, key):
        if key in self.cache and time.time() < self.ttl_cache[key]:
            return self.cache[key]
        else:
            del self.cache[key]
            del self.ttl_cache[key]
            return None

    def set(self, key, value, ttl=60):
        self.cache[key] = value
        self.ttl_cache[key] = time.time() + ttl

cache = Cache()
