import time

def api_call(url, data, retries=3):
    for i in range(retries):
        try:
            response = requests.post(url, data=data)
            if response.status_code == 429:
                # API rate limit exceeded, wait and retry
                print("API rate limit exceeded. Waiting before retrying...")
                time.sleep(60)
                continue
            elif response.status_code != 200:
                # Non-200 status code returned, raise an exception
                response.raise_for_status()
            else:
                return response.json()
        except Exception as e:
            print(f"Error calling API: {e}")
            if i < retries - 1:
                # Retry after waiting for some time
                print("Retrying after waiting...")
                time.sleep(10 * (i + 1))
                continue
            else:
                # Maximum number of retries reached, give up
                print("Maximum number of retries reached. Giving up.")
                return None

