class SearchCache:
    def __init__(self):
        self.cache = {}
        self.tags = {}

    def retrieve_documents(self, query, tag=None):
        if query in self.cache and (not tag or tag in self.tags.get(query, [])):
            print("Retrieving from cache...")
            return self.cache[query]
        else:
            print("Querying database...")
            time.sleep(5)  # Simulate long processing time
            results = [f"Document {i}" for i in range(10)]
            self.cache[query] = results
            if tag:
                self.tags.setdefault(query, set()).add(tag)
            return results

    def clear_cache(self, tag=None):
        if not tag:
            self.cache.clear()
            self.tags.clear()
        else:
            queries_to_clear = [q for q, tags in self.tags.items() if tag in tags]
            for query in queries_to_clear:
                del self.cache[query]
                self.tags[query].remove(tag)
                if not self.tags[query]:
                    del self.tags[query]

