import socket
from queue import Queue

class SocketPool:
    def __init__(self, max_size):
        self.max_size = max_size
        self.pool = Queue(maxsize=max_size)

    def acquire(self):
        if self.pool.qsize() == 0:
            return None
        return self.pool.get()

    def release(self, sock):
        if self.pool.qsize() < self.max_size:
            self.pool.put(sock)
        else:
            sock.close()

class NetworkRouter:
    def __init__(self):
