class Cache:
    def __init__(self):
        self.cache = {}

    def get(self, key):
        if key in self.cache and (time.time() - self.cache[key]['timestamp']) < 86400:
            print("Cache hit!")
            return self.cache[key]['value']
        else:
            print("Cache miss!")
            return None

    def set(self, key, value):
        self.cache[key] = {'value': value, 'timestamp': time.time()}

    def invalidate(self):
        for key in list(self.cache.keys()):
            if (time.time() - self.cache[key]['timestamp']) >= 86400:
