import numpy as np

def calculate_game_logic(game_state):
    # Naive implementation
    new_state = np.zeros_like(game_state)
    for i in range(game_state.shape[0]):
        for j in range(game_state.shape[1]):
            if game_state[i, j] == 1:
                neighbors = [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]
                for neighbor in neighbors:
                    if neighbor[0] >= 0 and neighbor[0] < game_state.shape[0] and \
                       neighbor[1] >= 0 and neighbor[1] < game_state.shape[1]:
                        new_state[neighbor] += 1
    return new_state

