import queue

class Frame:
    def __init__(self, width, height):
        self.width = width
        self.height = height

class FramePool:
    def __init__(self, max_size):
        self.max_size = max_size
        self.pool = queue.Queue(maxsize=max_size)

    def get_frame(self, width, height):
        try:
            frame = self.pool.get_nowait()
            frame.width = width
            frame.height = height
        except queue.Empty:
            frame = Frame(width, height)
        return frame

    def release_frame(self, frame):
        if self.pool.qsize() < self.max_size:
            self.pool.put(frame)

class VideoProcessor:
    def __init__(self, pool_size=10):
        self.frame_pool = FramePool(pool_size)
        self.frames = []

    def process_frame(self, frame_data):
        # Get a frame from the pool or create a new one
        frame = self.frame_pool.get_frame(frame_data['width'], frame_data['height'])
        # Perform processing on the frame
        # ...
        self.frames.append(frame)
        # Release the frame back to the pool
        self.frame_pool.release_frame(frame)

