import logging

class CustomLogger(logging.Logger):
    def __init__(self, name, level=logging.NOTSET):
        super().__init__(name, level=level)
        self.addFilter(self.custom_filter)
        self.setFormatter(self.custom_formatter)

    def custom_filter(self, record):
        return "suspicious" not in record.getMessage()

    def custom_formatter(self, record):
        log_time = record.created
        message = record.getMessage()
        level = record.levelname
        return f"{log_time} - {level}: {message}"

