import heapq

def dijkstra_algorithm(graph, start_node, end_node):
    shortest_distances = {}
    predecessor_nodes = {}
    unseen_nodes = [(0, start_node)]
    infinity = float('inf')
    path = []

    for node in graph:
        shortest_distances[node] = infinity
    shortest_distances[start_node] = 0

    while unseen_nodes:
        (current_distance, current_node) = heapq.heappop(unseen_nodes)
        if current_distance > shortest_distances[current_node]:
            continue
        for neighbor_node, weight in graph[current_node].items():
            distance = current_distance + weight
            if distance < shortest_distances[neighbor_node]:
                shortest_distances[neighbor_node] = distance
                predecessor_nodes[neighbor_node] = current_node
                heapq.heappush(unseen_nodes, (distance, neighbor_node))

    current_node = end_node
    while current_node != start_node:
        try:
            path.insert(0, current_node)
            current_node = predecessor_nodes[current_node]
        except KeyError:
            print('Path not reachable')
            break
    path.insert(0, start_node)

    if shortest_distances[end_node] != infinity:
        return path, shortest_distances[end_node]

