import math

class DistanceCalculator:
    def __init__(self, points):
        self.points = points
        self.distances = {}

    def calculate_distance(self, i, j):
        if (i, j) in self.distances:
            return self.distances[(i, j)]
        elif (j, i) in self.distances:
            return self.distances[(j, i)]
        else:
            distance = math.sqrt(sum([(self.points[i][k]-self.points[j][k])**2 for k in range(len(self.points[i]))]))
            self.distances[(i, j)] = distance
            return distance

    def get_distances(self):
        n = len(self.points)
        distances = []
        for i in range(n):
            for j in range(i+1, n):
                distance = self.calculate_distance(i, j)
                distances.append(distance)
        return distances

