import pycuda.autoinit
import pycuda.driver as cuda
from pycuda.compiler import SourceModule

mod = SourceModule("""
    __global__ void apply_effect(float *frame, float *result, int width, int height) {
        int idx = threadIdx.x + blockIdx.x * blockDim.x;
        int idy = threadIdx.y + blockIdx.y * blockDim.y;
        if (idx < width && idy < height) {
            int offset = (idy * width + idx) * 3;
            result[offset] = frame[offset] * 2;
            result[offset+1] = frame[offset+1] * 2;
            result[offset+2] = frame[offset+2] * 2;
        }
    }
""")

def apply_effect(frame, effect):
    width, height, channels = frame.shape
    block_size = (16, 16, 1)
    grid_size = ((width + block_size[0] - 1) // block_size[0], (height + block_size[1] - 1) // block_size[1], 1)

    frame_gpu = cuda.mem_alloc(frame.nbytes)
    cuda.memcpy_htod(frame_gpu, frame)

    result_gpu = cuda.mem_alloc(frame.nbytes)
    apply_effect_kernel = mod.get_function("apply_effect")
    apply_effect_kernel(frame_gpu, result_gpu, np.int32(width), np.int32(height), block=block_size, grid=grid_size)

    result = np.empty_like(frame)
    cuda.memcpy_dtoh(result, result_gpu)
    return result

