import requests
from functools import wraps

def circuit_breaker(n):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            consecutive_failures = 0
            while consecutive_failures < n:
                try:
                    result = func(*args, **kwargs)
                    consecutive_failures = 0
                    return result
                except ConnectionError as e:
                    consecutive_failures += 1
                    print(f"Attempt failed: {e}. Consecutive failures: {consecutive_failures}")
            raise ConnectionError(f"Function failed after {n} consecutive failures.")
        return wrapper
    return decorator

