class InvertedIndex:
    def __init__(self):
        self.index = {}

    def add_document(self, document_id, text):
        words = re.findall(r'\w+', text.lower())
        for word in words:
            if word not in self.index:
                self.index[word] = set()
            self.index[word].add(document_id)

    def search(self, query):
        words = re.findall(r'\w+', query.lower())
        results = None
        for word in words:
            if word in self.index:
                if results is None:
                    results = self.index[word]
                else:
                    results = results.intersection(self.index[word])
        if results is None:
            return []
        else:
            return list(results)

