        if query in self.cache:
            print(f"Using cached results for query '{query}'")
            return self.cache[query]

        # Code to perform actual search and store results in cache
        results = ["result1", "result2", "result3"]
        self.cache[query] = results

        # Check if cache size exceeds the limit
        if len(self.cache) > self.max_cache_size:
            self.cleanup_cache()

        return results

    def cleanup_cache(self):
        current_time = time.time()
        if (current_time - self.last_cache_cleanup_time) < self.cache_expiration_time:
            return

        expired_keys = []
        for key, value in self.cache.items():
            if (current_time - value["timestamp"]) > self.cache_expiration_time:
                expired_keys.append(key)

        for key in expired_keys:
            del self.cache[key]

