import sqlite3

class QueryError(Exception):
    def __init__(self, message, table=None, column=None):
        super().__init__(message)
        self.table = table
        self.column = column

class DatabaseConnection:
    def __init__(self, database):
        self.database = database

    def get_connection(self):
        conn = sqlite3.connect(self.database)
        return conn

    def close_connection(self, conn):
        conn.close()

    def execute_query(self, query):
        conn = self.get_connection()
        cursor = conn.cursor()
        try:
            cursor.execute(query)
            results = cursor.fetchall()
        except sqlite3.Error as e:
            if "no such table" in str(e):
                table_name = query.split()[3]
                raise QueryError(f"Table '{table_name}' does not exist", table=table_name)
            elif "no such column" in str(e):
                column_name = str(e).split()[-1].strip("'\"")
                raise QueryError(f"Column '{column_name}' does not exist", column=column_name)
            else:
                raise QueryError(f"Error executing query '{query}': {e}")
        finally:
            self.close_connection(conn)
        return results

