        self.cache = {}
        self.queue = deque()

    def get(self, key):
        if key in self.cache:
            self.queue.remove(key)
            self.queue.appendleft(key)
            return self.cache[key]['data']
        else:
            return None

    def put(self, key, value, last_modified):
        if len(self.cache) >= self.max_size:
            old_key = self.queue.pop()
