import json

class JSONParser:
    def __init__(self, file_path):
        self.file_path = file_path

    def parse(self):
        with open(self.file_path, 'r') as file:
            data = self._parse_json_recursive(json.load(file))
        return data

    def _parse_json_recursive(self, obj):
        if isinstance(obj, dict):
            for key in obj:
                obj[key] = self._parse_json_recursive(obj[key])
        elif isinstance(obj, list):
            for i in range(len(obj)):
                obj[i] = self._parse_json_recursive(obj[i])
        elif isinstance(obj, str):
            try:
                obj = int(obj)
            except ValueError:
                pass
        return obj

