class Cache:
    def __init__(self, max_size, eviction_policy='LRU'):
        self.max_size = max_size
        self.eviction_policy = eviction_policy
        self.data = {}

    def cache_data(self, key, value):
        if len(self.data) >= self.max_size:
            if self.eviction_policy == 'FIFO':
                oldest_key = min(self.data.keys(), key=lambda k: self.data[k]['timestamp'])
            elif self.eviction_policy == 'LIFO':
                oldest_key = max(self.data.keys(), key=lambda k: self.data[k]['timestamp'])
            else:
                # Default to LRU
                oldest_key = min(self.data.keys(), key=lambda k: self.data[k]['timestamp'])
            del self.data[oldest_key]
        timestamp = datetime.now()
        self.data[key] = {'value': value, 'timestamp': timestamp}

    def get_cached_data(self, key):
        if key in self.data:
            return self.data[key]['value']
        else:
