class GenerationalGarbageCollector:
    def __init__(self):
        self.generation_0 = []
        self.generation_1 = []
        self.generation_2 = []

    def add_object(self, obj):
        self.generation_0.append(obj)

    def collect(self):
        self.generation_2 = self.generation_1
        self.generation_1 = self.generation_0
        self.generation_0 = []
