from abc import ABC, abstractmethod

class Observer(ABC):
    @abstractmethod
    def update(self):
        pass

class Subject(ABC):
    def __init__(self):
        self.observers = []

    def attach(self, observer):
        self.observers.append(observer)

    def detach(self, observer):
        self.observers.remove(observer)

    def notify(self):
        for observer in self.observers:
            observer.update()

class Player(Observer):
    def __init__(self, name):
        self.name = name
        self.position = (0, 0)

    def move(self, x, y):
        self.position = (x, y)
        print(f"{self.name} moved to position {self.position}")
        self.notify()

    def update(self):
        print(f"{self.name}'s position is now {self.position}")

class Game(Subject):
    def __init__(self):
        super().__init__()
        self.players = []

    def add_player(self, player):
        self.players.append(player)
        self.attach(player)

    def play(self):
        for player in self.players:
            player.move(1, 1)

