def merge_dicts(default_dict, user_dict):
    merged_dict = default_dict.copy()
    for key, value in user_dict.items():
        if key not in merged_dict:
            merged_dict[key] = value
        elif isinstance(value, dict):
            merged_dict[key] = merge_dicts(merged_dict[key], value)
        else:
            merged_dict[key] = value
    return merged_dict

class TestMergeDicts(unittest.TestCase):

    def test_merge(self):
        default_dict = {'a': 1, 'b': 2, 'c': {'d': 3}}
        user_dict = {'b': 4, 'c': {'e': 5}}
        expected_result = {'a': 1, 'b': 4, 'c': {'d': 3, 'e': 5}}
        self.assertEqual(merge_dicts(default_dict, user_dict), expected_result)

    def test_no_overwrite(self):
        default_dict = {'a': 1, 'b': 2}
        user_dict = {'c': 3}
        expected_result = {'a': 1, 'b': 2, 'c': 3}
        self.assertEqual(merge_dicts(default_dict, user_dict), expected_result)

    def test_nested_dict(self):
        default_dict = {'a': 1, 'b': {'c': 2}}
        user_dict = {'b': {'d': 3}}
        expected_result = {'a': 1, 'b': {'c': 2, 'd': 3}}
        self.assertEqual(merge_dicts(default_dict, user_dict), expected_result)

