def error_handler(func):
    def wrapper(*args, **kwargs):
        max_retries = 3
        retries = 0
        while retries < max_retries:
            try:
                result = func(*args, **kwargs)
                return result
            except Exception as e:
                logging.error(f"Error in function {func.__name__}: {e}")
                retries += 1
                time.sleep(5)
