class WeatherForecast:
    def __init__(self, data):
        self.data = data

    def _get_trend(self, x, y):
        n = len(x)
        denominator = n * sum([x[i]**2 for i in range(n)]) - sum(x)**2
        if denominator == 0:
            slope = 0
        else:
            slope = (n * sum([x[i] * y[i] for i in range(n)]) - sum(x) * sum(y)) / denominator
        intercept = (sum(y) - slope * sum(x)) / n
        return slope, intercept

    def predict_weather(self, date):
        x = [i for i in range(len(self.data))]
        y = self.data
        slope, intercept = self._get_trend(x, y)
        return slope * date + intercept

