class APICircuitBreaker:
    def __init__(self, primary_endpoint, backup_endpoint, timeout=5, max_failures=3):
        self.primary_endpoint = primary_endpoint
        self.backup_endpoint = backup_endpoint
        self.timeout = timeout
        self.max_failures = max_failures
        self.failures = 0
        self.last_failure_time = None

    def is_available(self):
        if self.failures >= self.max_failures and time.time() - self.last_failure_time < self.timeout:
            return False
        try:
            response = requests.get(self.primary_endpoint)
            if response.status_code == 200:
                self.failures = 0
                return True
            else:
                self.failures += 1
                self.last_failure_time = time.time()
                return False
        except:
            self.failures += 1
            self.last_failure_time = time.time()
            return False

    def get_data(self, symbol):
        if self.is_available():
            url = f"{self.primary_endpoint}/{symbol}"
        else:
            url = f"{self.backup_endpoint}/{symbol}"
        response = requests.get(url)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception("Both API endpoints are down.")

