    if interest_rate == 0:
        return loan_amount / (30 * 12)
    monthly_interest_rate = interest_rate / 12
    num_payments = 30 * 12
    return loan_amount * (monthly_interest_rate * (1 + monthly_interest_rate) ** num_payments) / ((1 + monthly_interest_rate) ** num_payments - 1)

