class LazyFileLoader:
    def __init__(self, file_path):
        self.file_path = file_path
        self.lines_cache = {}

    def get_line(self, line_number):
        if line_number in self.lines_cache:
            print(f"Retrieving cached line {line_number}")
            return self.lines_cache[line_number]
        else:
            print(f"Loading line {line_number} from file...")
            with open(self.file_path, 'r') as f:
                for i, line in enumerate(f):
                    if i == line_number:
                        self.lines_cache[line_number] = line
                        return line

    def get_lines(self, start_line, end_line):
        lines = []
        for i in range(start_line, end_line+1):
            lines.append(self.get_line(i))
        return lines

def load_large_file(file_path):
    loader = LazyFileLoader(file_path)
