def calculate_similarity(item1, item2, metric):
    if metric == "cosine":
        numerator = sum([item1[i] * item2[i] for i in range(len(item1))])
        denominator = math.sqrt(sum([i**2 for i in item1])) * math.sqrt(sum([i**2 for i in item2]))
        return numerator / denominator
    elif metric == "euclidean":
        distance = math.sqrt(sum([(item1[i] - item2[i])**2 for i in range(len(item1))]))
        return 1 / (1 + distance)
    else:
