def dijkstra(start, end):
    heap = [(0, start)]
    visited = set()
    while heap:
        (cost, curr_user) = heapq.heappop(heap)
        if curr_user == end:
            return cost
        if curr_user in visited:
            continue
        visited.add(curr_user)
        for (friend, weight) in curr_user.friends:
            if friend not in visited:
                heapq.heappush(heap, (cost + weight, friend))
    return -1

