from termcolor import colored

def check_math_problem(problem):
    stack = []
    for i, char in enumerate(problem):
        if char == '(' or char == '[' or char == '{':
            stack.append((char, i))
        elif char == ')' and (not stack or stack[-1][0] != '('):
            print(colored(f"Error: unmatched ')'", 'red'))
            return False
        elif char == ']' and (not stack or stack[-1][0] != '['):
            print(colored(f"Error: unmatched ']'", 'red'))
            return False
        elif char == '}' and (not stack or stack[-1][0] != '{'):
            print(colored(f"Error: unmatched '}}'", 'red'))
            return False
        else:
            stack.pop()
    if stack:
        for bracket, index in stack:
            print(colored(f"Error: unmatched '{bracket}'", 'red'))
        return False
    return True

