import psycopg2
from queue import Queue

class ConnectionPool:
    def __init__(self, max_connections, dbname, user, password, host):
        self.max_connections = max_connections
        self.dbname = dbname
        self.user = user
        self.password = password
        self.host = host
        self.connections = Queue(maxsize=max_connections)

    def get_connection(self):
        if not self.connections.empty():
            return self.connections.get()
        else:
            return psycopg2.connect(
                dbname=self.dbname,
                user=self.user,
                password=self.password,
                host=self.host
            )

    def release_connection(self, conn):
        if self.connections.full():
            conn.close()
        else:
            self.connections.put(conn)

class Database:
    def __init__(self, pool):
        self.pool = pool

    def get_connection(self):
        return self.pool.get_connection()

def get_customer_data(customer_id):
    pool = ConnectionPool(10, "mydb", "user", "password", "localhost")
    db = Database(pool)
    conn = db.get_connection()
    cursor = conn.cursor()

    # Retrieve customer profile data
    cursor.execute(f"SELECT * FROM customers WHERE id={customer_id}")
    profile_data = cursor.fetchone()

    # Retrieve purchase history
    cursor.execute(f"SELECT * FROM purchases WHERE customer_id={customer_id}")
    purchase_history = cursor.fetchall()

    # Retrieve support tickets
    cursor.execute(f"SELECT * FROM tickets WHERE customer_id={customer_id}")
    support_tickets = cursor.fetchall()

    db.release_connection(conn)

    return {
        'profile': profile_data,
        'purchases': purchase_history,
        'tickets': support_tickets
    }

