import time

def retry_on_error(func):
    def wrapper(*args, **kwargs):
        max_retries = 3
        retries = 0
        while True:
            try:
                result = func(*args, **kwargs)
                return result
            except Exception as e:
                retries += 1
                if retries > max_retries:
                    raise e
                print(f"Error occurred: {e}. Retrying in 5 seconds...")
                time.sleep(5)
    return wrapper

