import threading

class ObjectPool:
    def __init__(self, num_objects, object_type):
        self.num_objects = num_objects
        self.object_type = object_type
        self.pool = [object_type() for _ in range(num_objects)]
        self.objects_in_use = set()

    def acquire_object(self):
        if not self.pool:
            raise ValueError("No objects available in the pool")
        obj = self.pool.pop()
        self.objects_in_use.add(obj)
        return obj

    def release_object(self, obj):
        if obj not in self.objects_in_use:
            raise ValueError("Object is not in use")
        self.objects_in_use.remove(obj)
        self.pool.append(obj)

class ThreadPool:
    def __init__(self, num_threads):
        self.num_threads = num_threads
        self.pool = [threading.Thread(target=self.worker) for _ in range(num_threads)]
        self.tasks = []
        self.object_pool = ObjectPool(num_threads, threading.Thread)

    def add_task(self, task):
        self.tasks.append(task)

    def start(self):
        for thread in self.pool:
            thread.start()

    def join(self):
        for thread in self.pool:
            thread.join()

    def worker(self):
        while True:
            if not self.tasks:
                obj = self.object_pool.acquire_object()
                self.tasks.append(obj)
            task = self.tasks.pop(0)
            task()

def task():
    print("Executing task...")
    pool.object_pool.release_object(threading.current_thread())

