import time

class Cache:
    def __init__(self):
        self.cache = {}

    def get(self, key):
        return self.cache.get(key)

    def set(self, key, value, expiration_time=3600):
        self.cache[key] = {'value': value, 'expiration_time': time.time() + expiration_time}

    def clear_expired_cache(self):
        current_time = time.time()
        expired_keys = []
        for key in self.cache:
            if self.cache[key]['expiration_time'] < current_time:
                expired_keys.append(key)
        for key in expired_keys:
            del self.cache[key]

