import time

def cache(func):
    results = {}
    def wrapper(*args, **kwargs):
        key = str(args) + str(kwargs)
        if key in results:
            print("Cache hit!")
            return results[key]
        else:
            print("Cache miss!")
            result = func(*args, **kwargs)
            results[key] = result
            return result
    return wrapper

