def balance_cache_partitions():
    num_nodes = len(cache_partitions)
    total_pages = sum(len(pages) for pages in cache_partitions.values())
    avg_pages_per_node = total_pages // num_nodes
    excess_pages = total_pages % num_nodes

    if excess_pages == 0:
        return

    nodes_with_excess = []
    for node, pages in cache_partitions.items():
        if len(pages) > avg_pages_per_node:
            nodes_with_excess.append(node)

    while excess_pages > 0 and len(nodes_with_excess) > 0:
