import requests
import secrets

class CSRFToken:
    def __init__(self):
        self.token = secrets.token_hex(16)

    def generate_token(self):
        return self.token

    def validate_token(self, token):
        return token == self.token

def add_csrf_token(func):
    def wrapper(*args, **kwargs):
        csrf_token = CSRFToken()
        kwargs['csrf_token'] = csrf_token.generate_token()
        response = func(*args, **kwargs)
        return response
    return wrapper

@add_csrf_token
def submit_form(form_data, csrf_token):
    headers = {'X-CSRF-Token': csrf_token}
    response = requests.post('https://example.com/submit', data=form_data, headers=headers)
    if not CSRFToken().validate_token(response.headers.get('X-CSRF-Token')):
        raise Exception("CSRF attack detected.")
    print(response.text)

