import datetime
import pytz

class DateTimeError(Exception):
    pass

def convert_to_utc(date_str, time_str, timezone):
    try:
        date = datetime.datetime.strptime(date_str, '%Y-%m-%d')
        time = datetime.datetime.strptime(time_str, '%H:%M:%S').time()
    except (ValueError, TypeError) as e:
        raise DateTimeError(f"Invalid date or time format: {e}")

    try:
        tz = pytz.timezone(timezone)
    except pytz.UnknownTimeZoneError:
        raise DateTimeError("Unknown timezone")

    local_time = datetime.datetime.combine(date, time, tzinfo=tz)
    utc_time = local_time.astimezone(datetime.timezone.utc)
    return utc_time.strftime('%Y-%m-%d %H:%M:%S')

