def extract_keywords(text):
    keywords = []
    for sentence in text.split('.'):
        words = sentence.strip().split(' ')
        for i, word in enumerate(words):
            if word.lower() == 'keyword':
                keyword_phrase = [word]
                j = i + 1
                while j < len(words) and len(keyword_phrase) < 3:
                    next_word = words[j]
                    if next_word.isalpha():
                        keyword_phrase.append(next_word)
                    j += 1
                keywords.append(' '.join(keyword_phrase))
    return keywords

