def generate_checksum(path):
    md5 = hashlib.md5()
    for root, dirs, files in os.walk(path):
        for file in files:
            filename = file.encode('utf-8')
            date_modified = str(datetime.datetime.fromtimestamp(os.path.getmtime(os.path.join(root, file)))).encode('utf-8')
            md5.update(filename + date_modified)
            with open(os.path.join(root, file), "rb") as f:
                while True:
                    data = f.read(4096)
                    if not data:
                        break
                    md5.update(data)
    return md5.hexdigest()

