class DistributionalModel:
    def __init__(self, corpus):
        self.corpus = corpus
        self.word_distribution = {}
        self.calculate_word_distribution()

    def calculate_word_distribution(self):
        total_words = sum(len(word) for word in self.corpus)
        for word in self.corpus:
            self.word_distribution[word] = len(word) / total_words

    def predict(self, source_text):
        source_words = source_text.split()
        target_words = []

        for word in source_words:
            max_score = 0
            max_word = None

            for target_word in self.corpus:
                score = self.word_distribution.get(target_word, 0) * self.score(word, target_word)

                if score > max_score:
                    max_score = score
                    max_word = target_word

            if max_word is not None:
                target_words.append(max_word)

        return ' '.join(target_words)

    def score(self, source_word, target_word):
        return sum(1 for s, t in zip(source_word, target_word) if s == t)

