def grade_assignment(assignment):
    sentences = assignment.split('.')
    total_words = 0
    total_syllables = 0
    for sentence in sentences:
        words = sentence.split()
        total_words += len(words)
        for word in words:
            syllables = count_syllables(word)
            total_syllables += syllables
    score = (0.39 * (total_words / len(sentences))) + (11.8 * (total_syllables / total_words)) - 15.59
    return round(score, 1)

def count_syllables(word):
    vowels = 'aeiouy'
    num_vowels = 0
    prev_char = None
    for char in word:
        if char.lower() in vowels and (prev_char is None or prev_char not in vowels):
            num_vowels += 1
        prev_char = char
    if word.endswith('e'):
        num_vowels -= 1
    if num_vowels == 0:
        num_vowels = 1
    return num_vowels

