def sort_list(transactions, attribute):
    for i in range(len(transactions)):
        min_index = i
        for j in range(i+1, len(transactions)):
            if getattr(transactions[j], attribute) < getattr(transactions[min_index], attribute):
                min_index = j
        transactions[i], transactions[min_index] = transactions[min_index], transactions[i]
    return transactions

