def calculate_average(data, index):
    current_period = data[index]
    previous_period = data[index-1] if index > 0 else None
    next_period = data[index+1] if index < len(data)-1 else None

    if previous_period is not None and next_period is not None:
        return (previous_period + current_period + next_period) / 3
    elif previous_period is not None:
        return (previous_period + current_period) / 2
    elif next_period is not None:
        return (current_period + next_period) / 2
    else:
        return current_period

def forecast_trends(data):
    trend_values = []
    for i in range(len(data)):
