def find_pattern(pattern, text):
    m = len(pattern)
    n = len(text)
    skip = {}
    for k in range(m):
        skip[pattern[k]] = m - k - 1
    i = m - 1
    while i < n:
        j = m - 1
        while text[i] == pattern[j]:
            if j == 0:
                return i
            i -= 1
            j -= 1
        i += max(skip.get(text[i], m), 1)
    return -1

