def share_code_snippet(code):
    # function to share code snippet on website
    pass

def toggle_indentation_guides(code):
    lines = code.split('\n')
    new_lines = []
    indent_level = 0
    for line in lines:
        if line.strip() == '':
            new_lines.append(line)
        else:
            num_spaces = len(line) - len(line.lstrip())
            if num_spaces > indent_level:
                new_lines.append(line.replace(' ' * (num_spaces - indent_level), '|' * indent_level))
                indent_level = num_spaces
            elif num_spaces < indent_level:
                new_lines.append(line.replace('|' * (indent_level - num_spaces), ' ' * num_spaces))
                indent_level = num_spaces
            else:
                new_lines.append(line)
                indent_level = num_spaces
    return '\n'.join(new_lines)

