def parse_json(json_str):
    data = json.loads(json_str)
    sensor_data = []
    for item in data:
        if isinstance(item, dict):
            if 'sensor' in item and 'value' in item:
                sensor_data.append((item['sensor'], item['value']))
            else:
                for key, value in item.items():
                    if isinstance(value, (dict, list)):
                        sensor_data.extend(parse_nested_json(key, value))
        elif isinstance(item, list):
            for nested_item in item:
                if isinstance(nested_item, (dict, list)):
                    sensor_data.extend(parse_nested_json(None, nested_item))
    return sensor_data

def parse_nested_json(parent_key, data):
    items = []
    if isinstance(data, dict):
        for key, value in data.items():
            new_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, (dict, list)):
                items.extend(parse_nested_json(new_key, value))
            elif value is not None:
                items.append((new_key, value))
    elif isinstance(data, list):
        for idx, item in enumerate(data):
            new_key = f"{parent_key}[{idx}]" if parent_key else str(idx)
            if isinstance(item, (dict, list)):
                items.extend(parse_nested_json(new_key, item))
            elif item is not None:
                items.append((new_key, item))
    return items

