def process_data(data):
    user_history = {}
    for user, item in data:
        if user not in user_history:
            user_history[user] = []
        user_history[user].append(item)

    item_counts = {}
    for user, history in user_history.items():
        for item in history:
            if item not in item_counts:
                item_counts[item] = 0
            item_counts[item] += 1

