from queue import Queue

class CodeEditor:
    def __init__(self, code):
        self.code = code
        self.collaborators = []
        self.edit_queue = Queue()

    def get_code(self):
        return self.code

    def set_code(self, new_code):
        self.code = new_code
        for collaborator in self.collaborators:
            collaborator.notify_edit(new_code)

    def add_collaborator(self, collaborator):
        self.collaborators.append(collaborator)

    def remove_collaborator(self, collaborator):
        self.collaborators.remove(collaborator)

    def process_edits(self):
        while True:
            edit = self.edit_queue.get()
            self.set_code(edit)
            self.edit_queue.task_done()

    def start_edit_thread(self):
        t = threading.Thread(target=self.process_edits)
        t.daemon = True
        t.start()

class Collaborator:
    def __init__(self, name, code_editor):
        self.name = name
        self.code_editor = code_editor

    def notify_edit(self, new_code):
        if new_code != self.code_editor.get_code():
            print(f"{self.name} received an update to the code editor.")
            self.code_editor.set_code(new_code)

    def make_edit(self, new_code):
