import subprocess
import re

class PackageManager:
    def __init__(self):
        self.packages = []

    def add_package(self, package):
        self.packages.append(package)

    def remove_package(self, package):
        self.packages.remove(package)

class PipPackageManager(PackageManager):
    def install_package(self, package):
        try:
            subprocess.check_call(["pip", "install", package])
            self.add_package(package)
        except subprocess.CalledProcessError as e:
            print(f"Error installing package '{package}': {e}")

    def uninstall_package(self, package):
        try:
            subprocess.check_call(["pip", "uninstall", "-y", package])
            self.remove_package(package)
        except subprocess.CalledProcessError as e:
            print(f"Error uninstalling package '{package}': {e}")

    def list_packages(self):
        pip_list_output = subprocess.check_output(["pip", "list"]).decode("utf-8")
        installed_packages = re.findall(r"^([\w-]+)\s+\(.*\)$", pip_list_output, flags=re.MULTILINE)
        self.packages = installed_packages

