from abc import ABC, abstractmethod

class SortingStrategy(ABC):
    @abstractmethod
    def sort(self, nums):
        pass

class QuickSortStrategy(SortingStrategy):
    def sort(self, nums):
        if len(nums) <= 1:
            return nums
        pivot = nums[0]
        left = []
        right = []
        for num in nums[1:]:
            if num < pivot:
                left.append(num)
            else:
                right.append(num)
        return self.sort(left) + [pivot] + self.sort(right)

class BubbleSortStrategy(SortingStrategy):
    def sort(self, nums):
        n = len(nums)
        for i in range(n):
            for j in range(n-i-1):
                if nums[j] > nums[j+1]:
                    nums[j], nums[j+1] = nums[j+1], nums[j]
        return nums

class Sorter:
    def __init__(self, nums, strategy):
        self.nums = nums
        self.strategy = strategy

    def set_strategy(self, strategy):
        self.strategy = strategy

    def sort(self):
        return self.strategy.sort(self.nums)

nums = [3, 1, 4, 2, 5]
