import random

def compute_mean(data):
    total = 0
    for value in data:
        total += value
    return total / len(data)

def compute_variance(data):
    mean = compute_mean(data)
    variance = 0
    for value in data:
        variance += (value - mean) ** 2
    return variance / len(data)

