import os

class Simulation:
    def __init__(self, name):
        self.name = name
        self.results = None

    def run(self):
        # Run simulation and generate results
        self.results = np.random.rand(10)

    def save(self):
        try:
            if not os.path.exists(f"{self.name}.txt"):
                with open(f"{self.name}.txt", 'w') as f:
                    np.savetxt(f, self.results)
            else:
                print(f"File {self.name}.txt already exists. Skipping save.")
        except Exception as e:
            print(f"Error saving file: {e}")

    def load(self):
        try:
            if os.path.exists(f"{self.name}.txt"):
                with open(f"{self.name}.txt", 'r') as f:
                    self.results = np.loadtxt(f)
            else:
                print(f"File {self.name}.txt does not exist. Loading default values.")
        except Exception as e:
            print(f"Error loading file: {e}")
            self.results = np.zeros(10)

