import os

class FileCache:
    def __init__(self):
        self.cache = {}

    def get(self, key):
        if key in self.cache:
            return self.cache[key]
        else:
            return None

    def set(self, key, value):
        self.cache[key] = value

    def delete(self, key):
        if key in self.cache:
            del self.cache[key]

    def clear(self):
        self.cache.clear()

def file_upload(file_path):
    cache = FileCache()
    cached_data = cache.get(file_path)
    if cached_data is not None:
        data = cached_data
    else:
        # Read data from external source
        with open(file_path, 'r') as f:
            data = f.read()
        cache.set(file_path, data)

    # Write data to disk
    with open(os.path.basename(file_path), 'w') as f:
        f.write(data)

file_upload('/path/to/file.txt')

