import time

class MyCache:
    def __init__(self):
        self.cache = {}

    def get(self, key):
        if key not in self.cache:
            return None

        data, timestamp = self.cache[key]
        if time.time() - timestamp > 60: # Expire after 60 seconds
            del self.cache[key]
            return None

        return data

    def set(self, key, value):
        self.cache[key] = (value, time.time())

cache = MyCache()
cache.set('patient1', {'name': 'Alice', 'age': 35, 'gender': 'female'})
time.sleep(5) # Wait for 5 seconds
print(cache.get('patient1')) # Should still be in cache
time.sleep(70) # Wait for 70 seconds
print(cache.get('patient1')) # Should be expired and return None

