import threading
import time

class Game:
    def __init__(self, game_id):
        self.game_id = game_id
        self.players = []
        self.is_running = False

    def add_player(self, player_id):
        self.players.append(player_id)

    def start_game(self):
        self.is_running = True
        # Simulate game logic and player interactions
        while self.is_running:
            time.sleep(1)
        print(f"Game {self.game_id} finished")

def stop_games(games):
    for game in games:
        game.is_running = False

games = []
for i in range(3):
    game = Game(i)
    for j in range(2):
        game.add_player(f"player{j}")
    games.append(game)

threads = []
for game in games:
    t = threading.Thread(target=game.start_game)
    threads.append(t)
    t.start()

# Graceful shutdown mechanism
for t in threads:
    t.join()

stop_games(games)

